using Fineage.Game;
using Fineage.Zone.Npcs;
using Xunit;

namespace Fineage.MobiusDiff.Tests;

/// <summary>
/// Differential golden matrix for Mobius <c>calcMagicDam</c> / <c>calcMagicSuccess</c> (#979 magic slice).
/// Each oracle is generated by the Java driver, which reads the Mobius skill / NPC XML (power, magicLevel, raw
/// NPC stats) and folds NPC M.Atk / M.Def exactly as <c>FuncMAtkMod</c> / <c>FuncMDefMod</c> do.
/// </summary>
public sealed class MagicMatrixTests
{
    static readonly string Root = RepoPaths.FindRoot();
    static readonly GameData Data = GameData.LoadDefault();
    static readonly NpcCatalog Npcs = NpcCatalog.LoadDefault();

    public static TheoryData<string> MagicScenarioIds
    {
        get
        {
            var data = new TheoryData<string>();
            foreach (var id in new[]
            {
                "magic-human-mystic-40-windstrike5-gremlin",
                "magic-human-mystic-40-hydroblast1-validus",
                "magic-human-mystic-40-flamestrike1-skeleton-guard",
                "magic-human-mystic-40-unarmed-windstrike5",
                "magic-elven-mystic-20-icebolt6-basilisk",
                "magic-dark-mystic-40-blaze1-critpower",
                "magic-human-mystic-40-windstrike5-vs-player"
            })
                data.Add(id);
            return data;
        }
    }

    static (Scenario Scenario, OracleFile Oracle) Load(string id)
    {
        string scenarioPath = Path.Combine(Root, "tools", "Fineage.MobiusDiff", "scenarios", id + ".json");
        var scenario = ScenarioJson.Load(scenarioPath);
        return (scenario, ScenarioJson.LoadOracle(Path.Combine(Root, scenario.Oracle.Golden)));
    }

    static DiffReport Run(string id, Action<ActualMetrics>? mutate = null)
    {
        var (scenario, oracle) = Load(id);
        return ScenarioRunner.Run(scenario, oracle, Data, Npcs, mutate);
    }

    static double Metric(DiffReport report, string name) =>
        Assert.Single(report.Rows, r => r.Parameter == name).Expected;

    [Theory]
    [MemberData(nameof(MagicScenarioIds))]
    public void Magic_scenario_matches_the_mobius_formula_oracle(string id)
    {
        var report = Run(id);
        Assert.True(report.Pass, string.Join("; ", report.Rows.Where(r => !r.Pass).Select(r => $"{r.Parameter} {r.Actual} != {r.Expected}")));
    }

    [Theory]
    [InlineData("targetMDef")]
    [InlineData("damageNormal")]
    [InlineData("magicSuccessRate")]
    [InlineData("damageCrit")]
    public void Negative_control_mutation_fails_a_magic_cell(string metric)
    {
        var report = Run("magic-human-mystic-40-hydroblast1-validus", actual => actual[metric] += 1);
        Assert.False(report.Pass);
        Assert.False(Assert.Single(report.Rows, r => r.Parameter == metric).Pass);
    }

    [Fact]
    public void Shots_double_and_quadruple_mAtk_inside_the_square_root()
    {
        var r = Run("magic-human-mystic-40-windstrike5-gremlin");
        double normal = Metric(r, "damageNormal");
        Assert.InRange(Metric(r, "damageSps") / normal, Math.Sqrt(2) - 0.01, Math.Sqrt(2) + 0.01);
        Assert.InRange(Metric(r, "damageBss") / normal, 2 - 0.01, 2 + 0.01);
    }

    [Fact]
    public void Crit_is_triple_for_pve_and_2_5_for_pvp_and_scales_with_magic_crit_damage_stat()
    {
        var plain = Run("magic-human-mystic-40-windstrike5-gremlin");
        Assert.InRange(Metric(plain, "damageCrit") / Metric(plain, "damageNormal"), 2.99, 3.01);
        Assert.InRange(Metric(plain, "damageCritPvp") / Metric(plain, "damageNormal"), 2.49, 2.51);
        var buffed = Run("magic-dark-mystic-40-blaze1-critpower");
        Assert.InRange(Metric(buffed, "damageCrit") / Metric(buffed, "damageNormal"), 4.4, 4.65);
    }

    [Fact]
    public void Success_rate_falls_with_level_gap_and_goes_negative_against_a_much_higher_target()
    {
        Assert.Equal(100, Metric(Run("magic-human-mystic-40-windstrike5-gremlin"), "magicSuccessRate"));
        Assert.Equal(92, Metric(Run("magic-human-mystic-40-hydroblast1-validus"), "magicSuccessRate"));
        Assert.True(Metric(Run("magic-human-mystic-40-windstrike5-vs-player"), "magicSuccessRate") < 0);
    }

    [Fact]
    public void Unarmed_caster_uses_five_plus_sqrt_level_random_and_a_weapon_uses_its_own()
    {
        Assert.Equal(11, Metric(Run("magic-human-mystic-40-unarmed-windstrike5"), "randomPercent"));
        Assert.Equal(20, Metric(Run("magic-human-mystic-40-windstrike5-gremlin"), "randomPercent"));
    }

    [Fact]
    public void Shield_block_adds_s_def_to_m_def_and_lowers_damage()
    {
        var r = Run("magic-human-mystic-40-flamestrike1-skeleton-guard");
        Assert.True(Metric(r, "damageShieldBlock") < Metric(r, "damageNormal"));
        Assert.Equal(1, Metric(r, "damagePerfectBlock"));
    }
}
